/** flat spans -> tree */
function buildTree(spans) {
  // Write your solution here
  const out = [];
  const byId = {};
  for (const s of spans) {
    const node = { name: s.name, ms: s.end - s.start, children: [] };
    byId[s.id] = node;
    if (s.parentId && byId[s.parentId]) byId[s.parentId].children.push(node);
    else out.push(node);
  }
  return out;
}

